const jwt = require('jsonwebtoken');
const axios = require('axios');
const fs = require('fs');
const path = require('path');

async function run() {
  const projectId = process.env.PARAGON_PROJECT_ID;
  const signingKey = process.env.PARAGON_SIGNING_KEY;
  const userId = 'test-user';

  if (!projectId || !signingKey) {
    console.error('PARAGON_PROJECT_ID and PARAGON_SIGNING_KEY must be set');
    process.exit(1);
  }

  // Ensure signing key is properly formatted if it's a PEM
  const formattedKey = signingKey.includes('-----BEGIN RSA PRIVATE KEY-----') 
    ? signingKey.replace(/\\n/g, '\n') 
    : signingKey;

  // Generate JWT
  const token = jwt.sign(
    {
      sub: userId,
      iat: Math.floor(Date.now() / 1000),
    },
    formattedKey,
    { algorithm: 'RS256', expiresIn: '1h' }
  );

  const baseUrl = `https://actionkit.useparagon.com/projects/${projectId}`;

  try {
    console.log('Fetching available actions...');
    const actionsResponse = await axios.get(`${baseUrl}/actions`, {
      headers: { Authorization: `Bearer ${token}` }
    });

    const actions = actionsResponse.data;
    // Paragon ActionKit actions usually follow the pattern "provider:action"
    // For Postgres it's often "postgres:executeQuery"
    const postgresAction = actions.find(a => 
      (a.name.toLowerCase().includes('postgres') || a.id.toLowerCase().includes('postgres')) && 
      (a.name.toLowerCase().includes('query') || a.id.toLowerCase().includes('query'))
    );

    if (!postgresAction) {
      console.error('Could not find Postgres execute query action. Available actions:', JSON.stringify(actions, null, 2));
      process.exit(1);
    }

    console.log(`Using action: ${postgresAction.name || postgresAction.id}`);

    // 2. Execute the query
    // The action name to use in POST /actions is usually the 'id' or 'name' from the list
    const actionToUse = postgresAction.id || postgresAction.name;

    console.log(`Executing query 'SELECT 1;' using action '${actionToUse}'...`);
    const executeResponse = await axios.post(`${baseUrl}/actions`, {
      action: actionToUse,
      parameters: {
        query: 'SELECT 1;'
      }
    }, {
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json'
      }
    });

    const resultPath = '/home/user/project/result.json';
    fs.mkdirSync(path.dirname(resultPath), { recursive: true });
    fs.writeFileSync(resultPath, JSON.stringify(executeResponse.data, null, 2));
    console.log(`Result saved to ${resultPath}`);

  } catch (error) {
    console.error('Error details:', error.response ? JSON.stringify(error.response.data, null, 2) : error.message);
    process.exit(1);
  }
}

